def cut_branch(src, name):
    pat = re.compile(r"^[ \t]*//[ \t]*={3,}[ \t]*" + re.escape(name) + r"[^\\n]*\\n", re.MULTILINE)
    m = pat.search(src)
    if not m:
        print("未找到:", name)
        return src
    start = m.start()
    ei = src.index("else if", start)
    b = src.index("{", ei)
    depth = 0
    i = b
    while i < len(src):
        if src[i] == "{": depth += 1
        elif src[i] == "}":
            depth -= 1
            if depth == 0:
                end = i + 1
                break
        i += 1
    while end < len(src) and src[end] in "\r\n":
        end += 1
    return src[:start] + src[end:]

for n in ["test-bt-callback", "test-events", "test-quality", "test-quality-callback"]:
    src = cut_branch(src, n)
    print("已删分支:", n)

open(path, "w", encoding="utf-8").write(src)
